using Azure.Search.Documents.Models;using EnterpriseDocumentIntelligence.BuildingBlocks.Messaging;
public static class IndexDocumentFactory{public static SearchDocument Create(Guid tenantId,Guid documentId,Guid versionId,EmbeddedChunk chunk,IReadOnlyCollection<Guid>? allowedPrincipals=null){if(tenantId==Guid.Empty||documentId==Guid.Empty||versionId==Guid.Empty)throw new ArgumentException("Tenant, document and version are required");if(string.IsNullOrWhiteSpace(chunk.Text))throw new ArgumentException("Chunk text is required");var d=new SearchDocument{{"id",chunk.ChunkId.ToString()},{"TenantId",tenantId.ToString()},{"DocumentId",documentId.ToString()},{"VersionId",versionId.ToString()},{"ChunkNumber",chunk.Number},{"Text",chunk.Text},{"TokenCount",chunk.TokenCount},{"ContentVector",chunk.Embedding},{"Citation",$"document:{documentId}/version:{versionId}/chunk:{chunk.Number}"},{"AllowedPrincipalIds",allowedPrincipals?.Select(x=>x.ToString()).ToArray()??Array.Empty<string>()}};return d;}}
public sealed class IndexingBatchBuilder{public IReadOnlyList<SearchDocument> Build(EmbeddingsCreated input,IReadOnlyCollection<Guid>? principals=null)=>input.Chunks.Select(x=>IndexDocumentFactory.Create(input.TenantId,input.DocumentId,input.VersionId,x,principals)).ToArray();}